import{c as a,Q as t,j as r,m as o}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"AgentCompass: Towards Reliable Evaluation of Agentic Workflows in Production","description":"","frontmatter":{"url":"https://arxiv.org/abs/2509.14647","title":"AgentCompass: Towards Reliable Evaluation of Agentic Workflows in Production","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2509.14647,"authors":["NVJK Kartik","Garvit Sapra","Rishav Hada","Nikhil Pareek"],"domains":["cs.AI"],"html":"https://arxiv.org/html/2509.14647v1","pdf_path":"pdfs/2509.14647.pdf","published_date":"2025-09-18T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2025-09-18-agentcompass-reliable-evaluation-agentic-workflows-2509-14647.md","filePath":"research/papers/2025-09-18-agentcompass-reliable-evaluation-agentic-workflows-2509-14647.md","lastUpdated":1785909234000}'),i={name:"research/papers/2025-09-18-agentcompass-reliable-evaluation-agentic-workflows-2509-14647.md"};function s(n,e,l,c,g,d){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="agentcompass-towards-reliable-evaluation-of-agentic-workflows-in-production" tabindex="-1">AgentCompass: Towards Reliable Evaluation of Agentic Workflows in Production <a class="header-anchor" href="#agentcompass-towards-reliable-evaluation-of-agentic-workflows-in-production" aria-label="Permalink to &quot;AgentCompass: Towards Reliable Evaluation of Agentic Workflows in Production&quot;">​</a></h1><p><strong>Authors</strong>: NVJK Kartik, Garvit Sapra, Rishav Hada, Nikhil Pareek <strong>Published</strong>: September 18, 2025 <strong>Source</strong>: <a href="https://arxiv.org/abs/2509.14647" target="_blank" rel="noreferrer">https://arxiv.org/abs/2509.14647</a> · <a href="https://arxiv.org/html/2509.14647v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2509.14647 <strong>Categories</strong>: cs.AI <strong>PDF</strong>: <a href="https://arxiv.org/abs/2509.14647" target="_blank" rel="noreferrer">research/papers/pdfs/2509.14647.pdf</a> (10 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>With the growing adoption of Large Language Models (LLMs) in automating complex, multi-agent workflows, organizations face mounting risks from errors, emergent behaviors, and systemic failures that current evaluation methods fail to capture. We present AgentCompass, the first evaluation framework designed specifically for post-deployment monitoring and debugging of agentic workflows. AgentCompass models the reasoning process of expert debuggers through a structured, multi-stage analytical pipeline: error identification and categorization, thematic clustering, quantitative scoring, and strategic summarization. The framework is further enhanced with a dual memory system-episodic and semantic-that enables continual learning across executions. Through collaborations with design partners, we demonstrate the framework&#39;s practical utility on real-world deployments, before establishing its efficacy against the publicly available TRAIL benchmark. AgentCompass achieves state-of-the-art results on key metrics, while uncovering critical issues missed in human annotations, underscoring its role as a robust, developer-centric tool for reliable monitoring and improvement of agentic systems in production.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出 <strong>AgentCompass</strong>——號稱首個專為 agentic workflows <strong>post-deployment 監控與 debugging</strong> 設計的 evaluation framework（非開發期評測，而是生產環境持續監測）。</li><li>將「資深 debugger 的推理流程」結構化為 <strong>multi-stage analytical pipeline</strong>：error identification/categorization → thematic clustering → quantitative scoring → strategic summarization。</li><li>引入 <strong>dual memory system</strong>（episodic + semantic），支援跨執行（across executions）的 continual learning，讓框架隨部署累積經驗。</li><li>以 design partners 的真實部署驗證實用性，並對標公開 <strong>TRAIL benchmark</strong> 量測效能。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>在 TRAIL benchmark 的 key metrics 上達成 <strong>state-of-the-art</strong>（論文宣稱；abstract 未列具體數字）。</li><li>能挖出 <strong>human annotations 遺漏的 critical issues</strong>——即模型發現了人工標註漏掉的問題，方法層意義 &gt; 單純分數。</li><li>真實部署（real-world deployments）case study 佐證 developer-centric 工具的實用性。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><p>文件 abstract 未列明確 limitation 章節（需查正文 PDF）。依現有資訊判斷的潛在弱點：</p><ul><li>「首個」「SOTA」屬作者宣稱，abstract 未給對照 baseline 與量化差距，需正文驗證。</li><li>評估框架本身以 LLM 為 judge（推測），存在 <strong>LLM-as-judge 自我偏誤 / 評測者本身需被評測</strong> 的遞迴問題——abstract 未說明如何校準 judge 可靠度。</li><li>dual memory 的 continual learning 可能引入 <strong>goal drift / 過擬合特定部署</strong> 風險，泛化性待查。</li><li>「uncovering issues missed in human annotations」缺乏 ground-truth 仲裁機制說明（究竟是真陽性還是 false positive 難分）。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>直接對應 <code>unverified_success</code> 閘門</strong>：本框架的核心命題（agentic workflow 自報成功 ≠ 真實可靠，需獨立評測層揪出隱性 failure）正是 core.md TEST 階段「subagent/workflow verdict 非證據，採信前必機械重驗」的學術版。⚠️ 落地門檻：AgentCompass 仍是 LLM-based judge，與本 workspace「確定性 gate 絕不經 sub-agent 中介」原則存在張力——不可直接拿它取代 grep/test/healthcheck 的確定性檢查。</li><li><strong>The Loop TEST／PGE 階段</strong>：multi-stage pipeline（識別→分群→評分→總結）與 <code>/deep-review</code> 的多維審查思路同構，可作為設計 <code>/pilot frontier</code> 稽核（原 <code>quality-pipeline</code>，v5.1 刪除） G-gate rubric 的參考。⚠️ 需先驗其 false-positive rate 再考慮借鑑。</li><li><strong>Advisor 模式 / dynamic workflow 三失敗模式</strong>：論文的 post-deployment 監控對應 <code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md）的 agentic laziness / self-preferential bias / goal drift 偵測需求；dual memory 的 continual learning 概念可對照 RECORD 階段「自我演化迴圈」，但 workspace 強調「機械驗證入庫、整合門控非自動」——AgentCompass 的自動 continual learning 若無獨立 evaluator 把關，與此安全邊界衝突。 〔v5.1：所引 workspace 細則已退役 → 見 <code>INDEX.md</code> §v5.1 規則退役對照〕</li><li>純研究歸檔，無既成程式碼整合建議；若要實驗其方法，建議 spawn 隔離 sub-agent 跑 TRAIL 復現再評估，不直接動 auto-load 規則。</li></ul>',17)])])}const h=a(i,[["render",s]]);export{p as __pageData,h as default};
